package contextbuild_test
import("context";"testing";"github.com/kzs0/reviewd/internal/contextbuild";"github.com/kzs0/reviewd/internal/storage")
func TestSnapshotCompatibilityAndInvalidation(t *testing.T){s:=contextbuild.Snapshot{ID:"s1",Repository:"r",Commit:"old",Artifacts:[]contextbuild.Artifact{{ID:"helper",SourceBlobs:[]string{"helper-v1"},Summary:"old helper"},{ID:"dependent",DependencyBlobs:[]string{"helper-v1"},Summary:"depends on old helper"},{ID:"unrelated",SourceBlobs:[]string{"other-v1"},Summary:"unrelated"}}};later:=contextbuild.Snapshot{ID:"s2",Repository:"r",Commit:"future"};wrong:=contextbuild.Snapshot{ID:"s3",Repository:"other",Commit:"head"};got,e:=contextbuild.Select([]contextbuild.Snapshot{s,later,wrong},"r",[]string{"old","head"});if e!=nil||got.ID!="s1"{t.Fatalf("selected incompatible context %#v %v",got,e)};if _,e=contextbuild.Select([]contextbuild.Snapshot{later},"r",[]string{"old","head"});e==nil{t.Fatal("unavailable context became compatible")};clean:=contextbuild.Invalidate(s,[]string{"helper-v1"});if len(clean.Artifacts)!=1||clean.Artifacts[0].ID!="unrelated"{t.Fatalf("stale summary remains %#v",clean)};if len(s.Artifacts)!=3{t.Fatal("mutated pinned snapshot")}}
func TestSnapshotsImmutableAndRetained(t *testing.T){ctx:=context.Background();store,e:=storage.Open(t.TempDir());if e!=nil{t.Fatal(e)};defer store.Close();a:=contextbuild.Snapshot{ID:"old",Repository:"r",Commit:"c1",IncorporatedTransitions:[]string{"t1"}};for i:=0;i<2;i++{if e=contextbuild.Publish(ctx,store,a);e!=nil{t.Fatal(e)}};mutated:=a;mutated.Commit="c2";if e=contextbuild.Publish(ctx,store,mutated);e==nil{t.Fatal("immutable ID overwritten")};b:=contextbuild.Snapshot{ID:"new",Repository:"r",Commit:"c2",IncorporatedTransitions:[]string{"t1","t2"}};if e=contextbuild.Publish(ctx,store,b);e!=nil{t.Fatal(e)};old,e:=contextbuild.Load(ctx,store,"old");if e!=nil||old.Commit!="c1"{t.Fatalf("compaction erased old snapshot %#v %v",old,e)};if e=contextbuild.Validate(contextbuild.Snapshot{});e==nil{t.Fatal("accepted missing identity")}}
